{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer kravet om varighed og prognosen (ikke væsentligt bedre inden for en længere årrække). Det udelader dog ét-års-udgangspunktet og muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed. Det konkluderer desuden, at en midlertidig tilstand 'ikke opfylder' kravet, og at betingelsen 'ikke er opfyldt', hvis den 'først senere er blevet kronisk/varig'. Det er forkert og i modstrid med vejledningen, hvor ca. ét års varighed kan gøre en ikke-varig tilstand varig. Svaret hævder også, at nævnspraksis kan føre til, at man 'mister grundlaget'. Det er ikke støttet."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Der er to af de fire kritiske elementer. Varighed som grundlæggende krav og prognosen om ingen væsentlig bedring, heller ikke ved behandling, er med. Der mangler omkring et års varighed og symptomer eller følger i mindst et år før ansøgningen. Der mangler også tidsbegrænset tillæg, når varighed er sandsynliggjort, men ikke endeligt fastslået."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvornår en funktionsnedsættelse er varig, og hvad der gælder, hvis den ikke er varig fra begyndelsen. Indholdet af det andet svar er delvis forkert, men det er ikke irrelevant."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser med nummererede noter og en kildeliste til SU-loven § 7, stk. 3, til forarbejder (L 182) og til tre nævnsafgørelser. Væsentlige udsagn kan derfor knyttes til identificerbare kilder."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Svaret citerer ikke SU-vejledningen (VEJ 10157) eller SU-bekendtgørelsen § 36-37, som er de autoritative og aktuelle kilder inden for den frosne afgrænsning. Det støtter sig i stedet på forarbejder til en 'senere SU-reform' fra 2019 og nævnsafgørelser fra 2013, 2019 og 2023. Disse er ikke de aktuelle autoritative kilder til varighedsvurderingen. Svaret markerer selv, at kilderne er 'uverificerede', og indeholder et '(uden kilde)'-mærke."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de angivne passager. Det gælder, at midlertidig tilstand ikke opfylder varighedskravet, og at man kan søge igen på nyt grundlag (note 5). Det gælder også, at nævnspraksis skulle vise, at man kan miste grundlaget, når tilstanden bliver kronisk, hvilket er logisk omvendt. Konklusionen er markeret '(uden kilde)'. Ingen af de angivne kilder støtter ét-års-udgangspunktet eller tidsbegrænset tillæg."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer retsvirkninger uden støtte i materialet. Det hævder, at en studerende kan miste grundlaget for støtte, fordi sygdommen er blevet kronisk eller langvarig. Det hævder også, at betingelsen ikke er opfyldt, hvis tilstanden 'først senere er blevet kronisk/varig'. Desuden fremhæver det som 'praktisk betydning', at man kan søge igen, når forløbet har ændret karakter."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer 'normalt' og 'udgangspunkt' i nogle passager. Det mister imidlertid den vigtigste kvalifikation, at omkring et års varighed kan gøre en ikke-varig tilstand varig, og at tidsforløbet ikke alene afgør spørgsmålet. Det mister også, at tidsbegrænset tillæg er en undtagelse ved sandsynliggjort varighed. Midlertidighed fremstilles som næsten udelukkende afslagsgrundlag."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Ræsonnementet er indre modstridende. Svaret siger, at et midlertidigt forløb kan begrunde støtte, men at kronisk udvikling falder uden for den midlertidige kategori. Det konkluderer samtidig, at en tilstand, der 'først senere er blevet kronisk/varig', ikke opfylder betingelsen. Det blander derfor varighed med midlertidighed og vender logikken om."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør noget absolut, som kilderne formulerer som udgangspunkt eller skøn. Betingelsen 'ikke opfyldt' for midlertidige eller senere varige tilstande står uden forbehold. Samtidig udelader svaret, at tidsbegrænset tillæg kan gives (kan-regel), og at ét år gælder som udgangspunkt ('omkring')."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "yes",
      "reason": "Svaret fastslår, at funktionsnedsættelsen skal være varig, og forklarer varighed som et prognosespørgsmål med henvisning til SU-loven § 7, stk. 3."
    },
    "A12": {
      "label": "no",
      "reason": "Svaret nævner ikke, at en ikke-varig tilstand kan vurderes varig efter omkring et år, eller at symptomer eller følger som udgangspunkt skal have varet mindst et år før ansøgningen. Det fremstiller tværtimod midlertidige tilstande som ikke opfyldende kravet."
    }
  },
  "overall_notes": "Svaret er delvis korrekt om varighedsbegrebet og prognosen, men det mangler vejledningens ét-års-udgangspunkt og muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed. Det bygger på uaktuelle eller uautoritative kilder, indeholder en intern modsigelse og tilføjer ustøttede retsvirkninger. Kildeangivelserne er formelt til stede, men støtter ikke de centrale påstande."
}

